import partnerJson from "./partner.json";
import type { ContentBlock } from "@/lib/assessments/content";

/**
 * Partner Earnings & Payout System (India 2026), generated by
 * scripts/site-content/build-partner.mjs. Shown on /partners and on the
 * professional sign-up pages so instructors know their perks up front.
 */

export type PartnerChapter = { id: string; title: string; lead: string; blocks: ContentBlock[] };
export type MatrixRow = { earner: string; activity: string; mode: string; default: string; evidence: string };

const data = partnerJson as unknown as {
  position: string;
  chapters: PartnerChapter[];
  matrix: MatrixRow[];
};

export const partnerPosition = data.position;
export const partnerChapters = data.chapters;

/** Earning-method codes from chapter 1 ("Earning methods"). */
export const methodNames: Record<string, string> = (() => {
  const ch = data.chapters.find((c) => c.id === "1");
  const t = ch?.blocks.find((b) => b.type === "table" && b.rows[0][0] === "Code") as
    | { type: "table"; rows: string[][] }
    | undefined;
  return Object.fromEntries((t?.rows.slice(1) ?? []).map((r) => [r[0], r[1]]));
})();

/** Which earner types each sign-up role covers. */
const earnersByRole: Record<string, string[]> = {
  educator: ["Teacher", "Tutor", "Course creator", "Creator", "Writer", "Video creator", "Question writer", "Evaluator", "Translator", "Speaker", "Judge", "Internship mentor", "CGC expert"],
  counsellor: ["Counsellor", "Psychologist", "Assessment expert", "Speaker", "CGC expert", "Reviewer"],
  trainer: ["Trainer", "Professional", "Mentor", "Course creator", "Speaker", "Internship mentor", "Judge", "CGC expert"],
  institute: ["Institution", "Olympiad coordinator", "Organiser", "Employer", "Coordinator", "Partner referrer"],
};

export function perksForRole(role: string): MatrixRow[] {
  const earners = earnersByRole[role];
  if (!earners) return [];
  return data.matrix.filter((r) => earners.includes(r.earner));
}

export function partnerChapter(id: string) {
  return data.chapters.find((c) => c.id === id);
}
